import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.1C62pOns.js";const n="/pro-agent-hub-installer/capturas/en/apps-detalhe.png",o="/pro-agent-hub-installer/capturas/en/apps-designer.png",b=JSON.parse('{"title":"Apps","description":"","frontmatter":{},"headers":[],"relativePath":"en/interface/apps.md","filePath":"en/interface/apps.md","lastUpdated":1791171177000}'),h={name:"en/interface/apps.md"};function r(p,e,l,d,c,g){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="apps" tabindex="-1">Apps <a class="header-anchor" href="#apps" aria-label="Permalink to &quot;Apps&quot;">​</a></h1><p>An <strong>App</strong> is a web screen built inside the platform: a form, a dashboard, a lookup. It has an address of its own, runs in a separate process and can be opened by people who are not ProAgentHub users.</p><p>It is the answer to &quot;what if the people who will use this shouldn&#39;t be signing into ProAgentHub?&quot;.</p><h2 id="general-tab" tabindex="-1">General tab <a class="header-anchor" href="#general-tab" aria-label="Permalink to &quot;General tab&quot;">​</a></h2><p><img src="'+n+'" alt="apps-detalhe"></p><p>Description, icon (how it appears in the menu) and the <strong>slug</strong> — the last part of the address, <code>/a/&lt;slug&gt;</code>.</p><p>The <strong>access mode</strong> decides who gets in:</p><ul><li><strong>Internal</strong> — requires a signed-in user, and respects groups.</li><li><strong>Public</strong> — anyone with the link opens it, with no login.</li></ul><div class="danger custom-block"><p class="custom-block-title">Public means public</p><p>In a public App there is no signed-in user: the page&#39;s code has nobody to identify, and everything it exposes is within reach of whoever has the address. Do not put anything behind a public App that you would not publish on an open page.</p></div><h2 id="global-tab" tabindex="-1">Global tab <a class="header-anchor" href="#global-tab" aria-label="Permalink to &quot;Global tab&quot;">​</a></h2><p>CSS, JavaScript and a <strong>global backend</strong> shared by every page. This is where the theme, the utilities and the functions several pages call all live.</p><h2 id="pages-tab" tabindex="-1">Pages tab <a class="header-anchor" href="#pages-tab" aria-label="Permalink to &quot;Pages tab&quot;">​</a></h2><p><img src="'+o+`" alt="apps-designer"></p><p>Each page declares how it is made, and that is a per-page choice:</p><ul><li><strong>Visual</strong> — assembled by dragging components in the designer. The HTML is generated from the tree.</li><li><strong>Code</strong> — HTML written by hand.</li></ul><div class="warning custom-block"><p class="custom-block-title">There is no sync back</p><p>Visual produces HTML; HTML is <strong>not</strong> turned back into a tree automatically. There is a code→visual import, but it is a one-off step you trigger on purpose, not a mirror. CSS and JS stay hand-editable in both modes — that is the escape hatch for whatever the designer does not cover.</p></div><h3 id="the-page-backend" tabindex="-1">The page backend <a class="header-anchor" href="#the-page-backend" aria-label="Permalink to &quot;The page backend&quot;">​</a></h3><p>Each page has a Python tab. <strong>Every top-level function whose name does not start with <code>_</code> becomes an endpoint</strong>, callable from the page&#39;s JavaScript with <code>proApp.call(&#39;name&#39;, {…})</code>.</p><p>There is no route and no decorator: the <strong>signature is the contract</strong>. The same reading of the code that builds the function list on screen validates the arguments that arrive — which is why the two cannot drift apart.</p><div class="tip custom-block"><p class="custom-block-title">Module state does not survive between calls</p><p>The scope is rebuilt on every request, because it carries the signed-in user. A global variable holds nothing from one call to the next. Whatever must persist goes into <code>db</code>.</p></div><h3 id="the-app-s-data" tabindex="-1">The App&#39;s data <a class="header-anchor" href="#the-app-s-data" aria-label="Permalink to &quot;The App&#39;s data&quot;">​</a></h3><p>Each App has a MongoDB database of its own, <code>app_&lt;id&gt;</code> — by the number, not the slug, so renaming an App never moves its data.</p><p>Code reaches it through the injected <code>db</code> or through the same operations loose in the scope (<code>save</code>, <code>find</code>, <code>delete</code>…). There is no connection to open, and no way to address another App&#39;s database. See <a href="/pro-agent-hub-installer/en/funcoes/app_backend">Page backend</a>.</p><p>The database is <strong>dropped along with the App</strong>.</p><h3 id="files-sent-through-the-page" tabindex="-1">Files sent through the page <a class="header-anchor" href="#files-sent-through-the-page" aria-label="Permalink to &quot;Files sent through the page&quot;">​</a></h3><p>Drag the <strong>File</strong> component into a form and give it a name — that name becomes the backend function&#39;s parameter, like any other field.</p><p>When the button that calls the function is clicked, the page sends the file first and hands Python its <strong>identifier</strong>. In the backend:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> receber</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(anexo: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">str</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) -&gt; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">str</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    dados </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> read_upload(anexo)          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># the bytes</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    info </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> upload_info(anexo)           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># name, type, size, who sent it</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Got </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">info[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;filename&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> with </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{len</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(dados)</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bytes&quot;</span></span></code></pre></div><p>With <strong>Multiple files</strong> ticked, the parameter arrives as a list of identifiers.</p><p>Files live in the <strong>App&#39;s own database</strong>, next to its data — and the same rules apply: there is no way to reach another App&#39;s file, they <strong>go away with the App</strong>, and they do <strong>not</strong> travel in the export (which carries structure, not production data). The size cap is the platform&#39;s, in <code>PRO_AI_MAX_FILE_SIZE</code>.</p><p>To list or delete: <code>list_uploads()</code> and <code>delete_upload(id)</code>. To offer the file back on screen, <code>proApp.fileLink(id)</code> returns the download address.</p><div class="warning custom-block"><p class="custom-block-title">In a public App, the download link only serves whoever uploaded</p><p>In an <strong>internal</strong> App the boundary is the same as the data&#39;s: whoever can open the App can download its files. In a <strong>public</strong> App it is not — the link only hands the file to the authenticated user who uploaded it, and whatever an anonymous visitor uploads does not come out of that address at all. Without this, a public form receiving a personal document would hand one visitor&#39;s document to any other: the file identifier is sequential enough to be guessed.</p><p>To show that content anyway, do it from the page <strong>backend</strong> — <code>read_upload(id)</code> returns the bytes, and there it is you who decides who sees what.</p></div><p>In a public App the upload also has a <strong>per-visitor quota</strong> (10 files or 100 MB every 10 minutes, by default). Whoever goes past it is asked to try again later: this is the only door on the platform where someone without an account writes to the database, and without a quota a single visitor would fill the installation&#39;s disk.</p><p>The count is kept <strong>in the memory of each replica</strong> of the service that publishes the Apps, and the default installation runs two of them: the ceiling the installation actually enforces is twice the configured number. If the limit has to be exact, run a single replica or tighten the value.</p><h2 id="preview-tab" tabindex="-1">Preview tab <a class="header-anchor" href="#preview-tab" aria-label="Permalink to &quot;Preview tab&quot;">​</a></h2><p>Runs the App as it will look, including content you have not saved yet. It is the same renderer that serves the published App, so what you see is what will ship.</p><p>The preview runs inside an isolated <code>iframe</code>, with no access to the hub&#39;s origin — the JavaScript you write cannot see the session of whoever is building it.</p><h2 id="versions-tab-and-publishing" tabindex="-1">Versions tab and publishing <a class="header-anchor" href="#versions-tab-and-publishing" aria-label="Permalink to &quot;Versions tab and publishing&quot;">​</a></h2><p>A version is a snapshot of the <strong>whole App</strong> — the header and every page. Publishing freezes one of those versions, and that is what answers at <code>/a/&lt;slug&gt;</code>.</p><p><strong>Editing the draft does not change what is live.</strong> Only publishing again does. That is what lets you work calmly on a screen that is in use.</p><h2 id="where-apps-show-up" tabindex="-1">Where Apps show up <a class="header-anchor" href="#where-apps-show-up" aria-label="Permalink to &quot;Where Apps show up&quot;">​</a></h2><p>To the people using it, a published App is <strong>an item on the side menu</strong>, not a row in a listing screen. Whoever builds sees the list under Apps; whoever consumes sees only the name and the icon you gave it.</p>`,42)])])}const k=a(h,[["render",r]]);export{b as __pageData,k as default};
